<div class="admin-pagehead"><div><span class="micro-label">COMUNIDAD SOLIDARIA</span><h1>Voluntariado</h1><p>Organiza jornadas y revisa postulaciones respetando los cupos.</p></div><a href="/admin/voluntariado/nueva" class="btn btn-primary">+ Nueva actividad</a></div><section class="admin-panel"><h2>Próximas y últimas actividades</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>Actividad</th><th>Fecha</th><th>Cupos</th><th>Estado</th></tr></thead><tbody><?php foreach($activities as $a):?><tr><td><strong><?= e($a['nombre']) ?></strong></td><td><?= e($a['fecha']) ?></td><td><?= (int)$a['cupos'] ?></td><td><?= e($a['estado']) ?></td></tr><?php endforeach ?></tbody></table></div></section><section class="admin-panel"><div class="panel-head"><h2>Solicitudes de voluntariado</h2><label class="mini-search">⌕ <input type="search" data-filter-table placeholder="Buscar personas..."></label></div><div class="table-scroll"><table class="data-table" data-table><thead><tr><th>Nombre</th><th>Correo</th><th>Actividad</th><th>Estado</th><th>Gestión</th></tr></thead><tbody><?php foreach($requests as $r):?><tr><td><?= e($r['nombre_completo']) ?></td><td><?= e($r['correo']) ?></td><td><?= e($r['actividad']) ?></td><td><span class="chip chip-soft"><?= e($r['estado']) ?></span></td><td><?php if($r['estado']==='pendiente'):?><form method="post" class="inline-actions" action="/admin/voluntariado/<?= (int)$r['id'] ?>/estado"><?= csrf_field() ?><button name="estado" value="aprobada" data-confirm="¿Aprobar esta postulación? Se comprobará disponibilidad de cupos.">Aprobar</button><button name="estado" value="rechazada" data-confirm="¿Rechazar esta postulación?">Rechazar</button></form><?php else: ?>—<?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section>
